@prefix fis: <http://example.org/onto/securities#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities> a owl:Ontology ;
    rdfs:label "Securities and Financial Instruments Ontology" ;
    rdfs:comment "An ontology modeling securities, financial instruments, bonds, stocks, derivatives, and related concepts as described in corpus passages drawn primarily from general finance encyclopedic sources, IAS/IFRS standards, ECB glossary, and finance education sources." .

#################################################################
# CLASSES
#################################################################

fis:FinancialInstrument a owl:Class ;
    rdfs:label "Financial Instrument" ;
    rdfs:comment "A monetary contract between parties that can be created, traded, modified and settled; any contract that gives rise to a financial asset of one entity and a financial liability or equity instrument of another entity (IAS 32)." .

fis:FinancialAsset a owl:Class ;
    rdfs:label "Financial Asset" ;
    rdfs:comment "Cash, an equity instrument of another entity, a contractual right to receive cash or another financial asset, or a contractual right to exchange financial assets/liabilities under potentially favourable conditions (IAS 32)." .

fis:FinancialLiability a owl:Class ;
    rdfs:label "Financial Liability" ;
    rdfs:comment "A contractual obligation to deliver cash or another financial asset to another entity, or to exchange financial assets/liabilities under potentially unfavourable conditions (IAS 32)." .

fis:EquityInstrument a owl:Class ;
    rdfs:label "Equity Instrument" ;
    rdfs:comment "Any contract that evidences a residual interest in the assets of an entity after deducting all of its liabilities (IAS 32)." .

fis:Security a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:label "Security" ;
    rdfs:comment "A tradable financial asset; a financial contract which entitles the holder to investment returns and which represents a claim on the issuer; legal definitions vary by jurisdiction." .

#### Top-level security taxonomy: Debt, Equity, Derivative, Hybrid, Fund

fis:DebtSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Debt Security" ;
    rdfs:comment "A negotiable financial instrument serving as evidence of a promise on the part of the issuer (debtor) to make one or more payments to the holder (creditor) on a specified future date or dates, usually consisting of principal and interest (coupon)." .

fis:EquitySecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Equity Security" ;
    rdfs:comment "A share of equity interest in an entity such as capital stock of a company, trust or partnership; a negotiable financial instrument representing ownership of a stake in a corporation." .

fis:Derivative a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:label "Derivative" ;
    rdfs:comment "A contract between a buyer and seller whose value is derived from the performance of an underlying entity such as an asset, index, interest rate, or event; involves an underlier, a future act, a price, and a future date." .

fis:HybridSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Hybrid Security" ;
    rdfs:comment "A security that combines some characteristics of both debt and equity securities, e.g., preference shares, convertibles." .

fis:Fund a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Fund" ;
    rdfs:comment "An investment vehicle that pools money from many investors and invests in a portfolio of other securities; value is derived from the underlying instruments it owns." .

owl:AllDisjointClasses [ owl:members ( fis:DebtSecurity fis:EquitySecurity fis:Derivative fis:HybridSecurity fis:Fund ) ] .

#### Debt security subtypes

fis:Bond a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "Bond" ;
    rdfs:comment "A type of security under which the issuer (debtor) owes the holder (creditor) a debt, obliged to provide cash flow consisting usually of repaying the principal at maturity and interest (coupon) over time; generally long-term." .

fis:MoneyMarketInstrument a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "Money Market Instrument" ;
    rdfs:comment "Short-term debt instrument with original maturity of one year or less, highly liquid, sometimes called 'near cash'; debt securities with term under one year are generally designated money market instruments rather than bonds." .

fis:GovernmentBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Government Bond" ;
    rdfs:comment "Also called sovereign bond or treasury bond; medium or long term debt security issued by a sovereign national government to support public spending." .

owl:equivalentClass [] .
fis:GovernmentBond owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ]
    )
] .

fis:MunicipalBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Municipal Bond" ;
    rdfs:comment "Known in the US as municipal bond ('muni'); bond issued by a local authority, state, provincial, territorial, municipal, or other sub-sovereign governmental unit, or entities they create." ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf ( fis:Bond
            [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:LocalGovernment ]
        )
    ] .

fis:SupranationalBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Supranational Bond" ;
    rdfs:comment "Also known as a 'supra'; bond representing the debt of international organizations such as the World Bank, IMF, or regional multilateral development banks." ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf ( fis:Bond
            [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ]
        )
    ] .

fis:CorporateBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Corporate Bond" ;
    rdfs:comment "A bond issued by a corporation in order to raise financing for operations, mergers & acquisitions, or expansion; strictly applies to corporations, excluding municipal bonds." ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf ( fis:Bond
            [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ]
        )
    ] .

owl:AllDisjointClasses [ owl:members ( fis:GovernmentBond fis:MunicipalBond fis:SupranationalBond fis:CorporateBond ) ] .

fis:WarBond a owl:Class ;
    rdfs:subClassOf fis:GovernmentBond ;
    rdfs:label "War Bond" ;
    rdfs:comment "A bond issued by a government to fund military operations and other expenditure during wartime, often with a low return rate." .

fis:ClimateBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Climate Bond" ;
    rdfs:comment "A bond issued by a government or corporate entity to raise finance for climate change mitigation- or adaptation-related projects." .

fis:RevenueBond a owl:Class ;
    rdfs:subClassOf fis:MunicipalBond ;
    rdfs:label "Revenue Bond" ;
    rdfs:comment "A municipal bond distinguished by guarantee of repayment solely from revenues generated by a specified revenue-generating entity; typically non-recourse." .

fis:GeneralObligationBond a owl:Class ;
    rdfs:subClassOf fis:MunicipalBond ;
    rdfs:label "General Obligation Bond" ;
    rdfs:comment "Principal and interest secured by the full faith and credit of the issuer, usually supported by taxing power; considered most secure type of municipal bond." .

fis:AssessmentBond a owl:Class ;
    rdfs:subClassOf fis:GeneralObligationBond ;
    rdfs:label "Assessment Bond" ;
    rdfs:comment "Promises repayment based on property tax assessments of properties located within the issuer's boundaries; generally considered a form of general obligation bond." .

owl:AllDisjointClasses [ owl:members ( fis:GeneralObligationBond fis:RevenueBond ) ] .

fis:HighYieldBond a owl:Class ;
    rdfs:subClassOf fis:CorporateBond ;
    rdfs:label "High-Yield Bond" ;
    rdfs:comment "Also called junk bond; rated below investment grade by credit rating agencies because of uncertainty that the issuer will pay interest and/or redeem the bond; investors expect higher yield." .

fis:InvestmentGradeBond a owl:Class ;
    rdfs:subClassOf fis:CorporateBond ;
    rdfs:label "Investment Grade Bond" ;
    rdfs:comment "Also called high-grade bond; rated AAA, AA, A, or BBB by credit rating agencies." .

owl:AllDisjointClasses [ owl:members ( fis:HighYieldBond fis:InvestmentGradeBond ) ] .

fis:AssetBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Asset-Backed Security" ;
    rdfs:comment "Bond whose interest and principal payments are backed by underlying cash flows from other assets, such as consumer loans, auto loans, credit card receivables, or student loans." .

fis:CoveredBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Covered Bond" ;
    rdfs:comment "Backed by cash flows from mortgages or public sector assets; unlike asset-backed securities, the assets remain on the issuer's balance sheet." .

fis:SubordinatedBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Subordinated Bond" ;
    rdfs:comment "Has lower priority than other bonds of the issuer in case of liquidation; paid after senior bondholders; usually has a lower credit rating than senior bonds." .

fis:SeniorBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Senior Bond" ;
    rdfs:comment "Bond holders that are first in line to be paid in case of bankruptcy, before subordinated bond holders." .

owl:AllDisjointClasses [ owl:members ( fis:SeniorBond fis:SubordinatedBond ) ] .

fis:SocialImpactBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Social Impact Bond" ;
    rdfs:comment "An agreement for public sector entities to pay back private investors after meeting verified improved social outcome goals resulting in public sector savings." .

fis:MortgageBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:AssetBackedSecurity ;
    rdfs:label "Mortgage-Backed Security" ;
    rdfs:comment "An asset-backed security secured by a mortgage or collection of mortgages; MBS where assets are mortgages." .

fis:ResidentialMortgageBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "Residential Mortgage-Backed Security" ;
    rdfs:comment "A pass-through MBS backed by mortgages on residential property, secured by single-family, one- to four-unit real estate." .

fis:CommercialMortgageBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "Commercial Mortgage-Backed Security" ;
    rdfs:comment "A pass-through MBS backed by mortgages on commercial property, secured by commercial and multi-family properties." .

owl:AllDisjointClasses [ owl:members ( fis:ResidentialMortgageBackedSecurity fis:CommercialMortgageBackedSecurity ) ] .

fis:CollateralizedMortgageObligation a owl:Class ;
    rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "Collateralized Mortgage Obligation" ;
    rdfs:comment "Also called 'pay-through bond'; a debt obligation of a legal entity collateralized by the assets it owns, divided into classes (tranches) with different maturities and priorities." .

fis:StrippedMortgageBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "Stripped Mortgage-Backed Security" ;
    rdfs:comment "SMBS where each mortgage payment is partly principal and partly interest, which can be separated into interest-only or principal-only components." .

fis:InterestOnlyStrip a owl:Class ;
    rdfs:subClassOf fis:StrippedMortgageBackedSecurity ;
    rdfs:label "Interest-Only Strip" ;
    rdfs:comment "A bond with cash flows backed by the interest component of property owner's mortgage payments." .

fis:PrincipalOnlyStrip a owl:Class ;
    rdfs:subClassOf fis:StrippedMortgageBackedSecurity ;
    rdfs:label "Principal-Only Strip" ;
    rdfs:comment "A bond with cash flows backed by the principal repayment component of property owner's mortgage payments." .

owl:AllDisjointClasses [ owl:members ( fis:InterestOnlyStrip fis:PrincipalOnlyStrip ) ] .

fis:CollateralizedDebtObligation a owl:Class ;
    rdfs:subClassOf fis:AssetBackedSecurity ;
    rdfs:label "Collateralized Debt Obligation" ;
    rdfs:comment "A type of structured asset-backed security backed by debt obligations, often other asset-backed securities; sliced into tranches catching cash flow in sequence based on seniority." .

fis:CertificateOfDeposit a owl:Class ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:label "Certificate of Deposit" ;
    rdfs:comment "A time deposit sold by banks, thrift institutions, and credit unions with a specific, fixed term before money can be withdrawn without penalty." .

fis:CommercialPaper a owl:Class ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:label "Commercial Paper" ;
    rdfs:comment "An unsecured promissory note with a fixed maturity of usually less than 270 days, issued by large corporations to meet short-term debt obligations." .

fis:TreasuryBill a owl:Class ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:label "Treasury Bill" ;
    rdfs:comment "Short-term debt obligation of a national government maturing in three to twelve months (or under one year); zero-coupon bond bought at a discount." .

fis:RepurchaseAgreement a owl:Class ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:label "Repurchase Agreement" ;
    rdfs:comment "Short-term loan arranged by selling securities to an investor with an agreement to repurchase them at a fixed price on a fixed date." .

fis:FixedRateBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Fixed Rate Bond" ;
    rdfs:comment "Bond with interest payments (coupon) that remain constant throughout the life of the bond." .

fis:FloatingRateNote a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Floating Rate Note" ;
    rdfs:comment "Bond with a variable coupon linked to a reference rate of interest such as LIBOR or SOFR, recalculated periodically." .

fis:ZeroCouponBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Zero-Coupon Bond" ;
    rdfs:comment "A bond in which the face value is repaid at maturity with no periodic coupon payments; issued at a substantial discount to par value." ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf ( fis:Bond
            [ a owl:Restriction ; owl:onProperty fis:hasCouponRate ; owl:hasValue "0"^^xsd:decimal ]
        )
    ] .

owl:AllDisjointClasses [ owl:members ( fis:FixedRateBond fis:FloatingRateNote fis:ZeroCouponBond ) ] .

fis:InflationIndexedBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Inflation-Indexed Bond" ;
    rdfs:comment "Also called 'linker' (US) or index-linked bond (UK); principal amount and interest payments are indexed to the level of consumer prices." .

fis:PerpetualBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Perpetual Bond" ;
    rdfs:comment "Also called perpetuity or 'Perp'; a bond with no maturity date." .

fis:SerialBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Serial Bond" ;
    rdfs:comment "A bond that matures in installments over a period of time." .

fis:CallableBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Callable Bond" ;
    rdfs:comment "A bond that gives the issuer the right to repay the bond before the maturity date on call dates." .

fis:PutableBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Putable Bond" ;
    rdfs:comment "Also called retractable bond; gives the holder the right to force the issuer to repay the bond before the maturity date on put dates." .

fis:BulletBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Bullet Bond" ;
    rdfs:comment "A straight bond that is neither callable nor putable." .

fis:ConvertibleBond a owl:Class ;
    rdfs:subClassOf fis:HybridSecurity, fis:Bond ;
    rdfs:label "Convertible Bond" ;
    rdfs:comment "Also called convertible note or convertible debenture (if maturity >10 years); a bond that the holder can convert into a specified number of shares of common stock in the issuing company or cash of equal value; a hybrid security with debt- and equity-like features." .

fis:ExchangeableBond a owl:Class ;
    rdfs:subClassOf fis:HybridSecurity, fis:Bond ;
    rdfs:label "Exchangeable Bond" ;
    rdfs:comment "Allows exchange to shares of a corporation other than the issuer." .

fis:MandatoryConvertibleBond a owl:Class ;
    rdfs:subClassOf fis:ConvertibleBond ;
    rdfs:label "Mandatory Convertible Bond" ;
    rdfs:comment "Forces the holder to convert into shares at maturity; often bears two conversion prices." .

fis:ContingentConvertibleBond a owl:Class ;
    rdfs:subClassOf fis:MandatoryConvertibleBond ;
    rdfs:label "Contingent Convertible Bond" ;
    rdfs:comment "Also known as CoCo; a variation of mandatory convertibles automatically converted into equity if a pre-specified trigger event occurs." .

fis:BearerBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Bearer Bond" ;
    rdfs:comment "An official certificate issued without a named holder; the person possessing the paper certificate can claim the value of the bond." .

fis:RegisteredBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Registered Bond" ;
    rdfs:comment "A bond whose ownership is recorded by the issuer or a transfer agent; opposite of bearer bond." .

fis:BookEntryBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Book-Entry Bond" ;
    rdfs:comment "A bond that does not have a paper certificate." .

owl:AllDisjointClasses [ owl:members ( fis:BearerBond fis:RegisteredBond fis:BookEntryBond ) ] .

fis:TreasuryNote a owl:Class ;
    rdfs:subClassOf fis:GovernmentBond ;
    rdfs:label "Treasury Note" ;
    rdfs:comment "US Treasury security with maturity of two, three, five, or ten years, with fixed coupon payments every six months." .

fis:TreasuryBond a owl:Class ;
    rdfs:subClassOf fis:GovernmentBond ;
    rdfs:label "Treasury Bond" ;
    rdfs:comment "US Treasury security with the longest maturity, from twenty to thirty years, with coupon payments every six months." .

fis:TreasuryInflationProtectedSecurity a owl:Class ;
    rdfs:subClassOf fis:GovernmentBond, fis:InflationIndexedBond ;
    rdfs:label "Treasury Inflation-Protected Security" ;
    rdfs:comment "TIPS; an inflation-indexed bond whose principal is adjusted to the Consumer Price Index." .

#### Equity subtypes

fis:Stock a owl:Class ;
    rdfs:subClassOf fis:EquitySecurity ;
    rdfs:label "Stock" ;
    rdfs:comment "Also called share; consists of all shares by which ownership of a corporation is divided; a type of security giving stockholders a share of ownership in a company." .

fis:CommonStock a owl:Class ;
    rdfs:subClassOf fis:Stock ;
    rdfs:label "Common Stock" ;
    rdfs:comment "Also called ordinary share or voting share; a form of corporate equity ownership typically carrying voting rights and entitlement to residual profits, lowest priority in payouts." .

fis:PreferredStock a owl:Class ;
    rdfs:subClassOf fis:Stock, fis:HybridSecurity ;
    rdfs:label "Preferred Stock" ;
    rdfs:comment "Also called preference shares; senior to common stock but subordinate to bonds; typically no voting rights but priority in dividends and liquidation; generally considered a hybrid instrument." .

owl:AllDisjointClasses [ owl:members ( fis:CommonStock fis:PreferredStock ) ] .

fis:ConvertiblePreferredStock a owl:Class ;
    rdfs:subClassOf fis:PreferredStock ;
    rdfs:label "Convertible Preferred Stock" ;
    rdfs:comment "Preferred stock that includes the ability of the holder to convert the preferred shares into a fixed number of common shares." .

fis:CumulativePreferredStock a owl:Class ;
    rdfs:subClassOf fis:PreferredStock ;
    rdfs:label "Cumulative Preferred Stock" ;
    rdfs:comment "Requires that if a company fails to pay a dividend, it must make up for it at a later time before paying common-stock dividends again." .

fis:NoncumulativePreferredStock a owl:Class ;
    rdfs:subClassOf fis:PreferredStock ;
    rdfs:label "Noncumulative Preferred Stock" ;
    rdfs:comment "Also called straight preferred stock; any dividends passed are lost if not declared." .

owl:AllDisjointClasses [ owl:members ( fis:CumulativePreferredStock fis:NoncumulativePreferredStock ) ] .

fis:DepositaryReceipt a owl:Class ;
    rdfs:subClassOf fis:EquitySecurity ;
    rdfs:label "Depositary Receipt" ;
    rdfs:comment "A negotiable financial instrument issued by a bank to represent a foreign company's publicly traded securities, traded on a local stock exchange." .

fis:AmericanDepositaryReceipt a owl:Class ;
    rdfs:subClassOf fis:DepositaryReceipt ;
    rdfs:label "American Depositary Receipt" ;
    rdfs:comment "Depositary receipt listed and traded in the United States." .

fis:EuropeanDepositaryReceipt a owl:Class ;
    rdfs:subClassOf fis:DepositaryReceipt ;
    rdfs:label "European Depositary Receipt" ;
    rdfs:comment "Depositary receipt issued by European banks." .

fis:GlobalDepositaryReceipt a owl:Class ;
    rdfs:subClassOf fis:DepositaryReceipt ;
    rdfs:label "Global Depositary Receipt" ;
    rdfs:comment "Depositary receipt issued by banks other than US or European issuers." .

owl:AllDisjointClasses [ owl:members ( fis:AmericanDepositaryReceipt fis:EuropeanDepositaryReceipt fis:GlobalDepositaryReceipt ) ] .

#### Hybrid subtypes

fis:PreferenceShare a owl:Class ;
    rdfs:subClassOf fis:HybridSecurity ;
    rdfs:label "Preference Share" ;
    rdfs:comment "Forms an intermediate class of security between equities and debt; right to receive interest or return of capital prior to ordinary shareholders upon liquidation." .

fis:Convertible a owl:Class ;
    rdfs:subClassOf fis:HybridSecurity ;
    rdfs:label "Convertible" ;
    rdfs:comment "Bonds or preferred stocks that can be converted, at the election of the holder, into ordinary shares of the issuing company." .

fis:EquityWarrant a owl:Class ;
    rdfs:subClassOf fis:HybridSecurity ;
    rdfs:label "Equity Warrant" ;
    rdfs:comment "Options issued by the company allowing the holder to purchase a specific number of shares at a specified price within a specified time; often issued with bonds or existing equities." .

#### Derivative subtypes

fis:Forward a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "Forward" ;
    rdfs:comment "A non-standardized contract between two parties to buy or sell an asset at a specified future time at an amount agreed upon today; not exchange-traded." .

fis:Future a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "Future" ;
    rdfs:comment "A standardized contract between two parties to buy or sell a specified asset of standardized quantity and quality for a price agreed today, with delivery and payment at a specified future date; traded on a futures exchange." .

fis:Option a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "Option" ;
    rdfs:comment "A contract which gives the buyer the right, but not the obligation, to buy or sell an underlying asset at a specified strike price on or before a specified date." .

fis:CallOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Call Option" ;
    rdfs:comment "An option that conveys to the owner the right to buy something at a certain (strike) price." .

fis:PutOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Put Option" ;
    rdfs:comment "An option that conveys to the owner the right to sell something at a certain (strike) price." .

owl:AllDisjointClasses [ owl:members ( fis:CallOption fis:PutOption ) ] .

fis:AmericanOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "American Option" ;
    rdfs:comment "An option that may be exercised on any trading day on or before expiration." .

fis:EuropeanOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "European Option" ;
    rdfs:comment "An option that may only be exercised on expiry." .

owl:AllDisjointClasses [ owl:members ( fis:AmericanOption fis:EuropeanOption ) ] .

fis:BermudanOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Bermudan Option" ;
    rdfs:comment "An option that may be exercised only on specified dates on or before expiration." .

fis:AsianOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Asian Option" ;
    rdfs:comment "An option whose payoff is determined by the average underlying price over some preset time period." .

fis:BarrierOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Barrier Option" ;
    rdfs:comment "An option with the characteristic that the underlying security's price must pass a certain barrier before it can be exercised." .

fis:BinaryOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Binary Option" ;
    rdfs:comment "An all-or-nothing option that pays the full amount if the underlying security meets the defined condition on expiration." .

fis:Warrant a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Warrant" ;
    rdfs:comment "A long-dated option, generally traded over the counter, with a maturity period longer than the commonly used short-dated options." .

fis:ExchangeTradedOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Exchange-Traded Option" ;
    rdfs:comment "Also called listed option; standardized contract settled through a clearing house, with fulfillment guaranteed by a clearing corporation." .

fis:OverTheCounterOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Over-the-Counter Option" ;
    rdfs:comment "Also called dealer option; traded between two private parties, not listed on an exchange, with unrestricted and individually tailored terms." .

owl:AllDisjointClasses [ owl:members ( fis:ExchangeTradedOption fis:OverTheCounterOption ) ] .

fis:Swap a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "Swap" ;
    rdfs:comment "A derivative in which two counterparties exchange cash flows of one party's financial instrument for those of the other party's financial instrument." .

fis:InterestRateSwap a owl:Class ;
    rdfs:subClassOf fis:Swap ;
    rdfs:label "Interest Rate Swap" ;
    rdfs:comment "A contractual agreement with a counterparty to exchange cash flows representing streams of periodic interest payments in one currency, typically fixed-rate for variable-rate." .

fis:CurrencySwap a owl:Class ;
    rdfs:subClassOf fis:Swap ;
    rdfs:label "Currency Swap" ;
    rdfs:comment "A contractual agreement to exchange cash flows representing streams of periodic interest payments in two different currencies." .

fis:CreditDefaultSwap a owl:Class ;
    rdfs:subClassOf fis:Swap ;
    rdfs:label "Credit Default Swap" ;
    rdfs:comment "A financial swap agreement in which the seller will compensate the buyer in the event of a loan default or other credit event by the debtor; a type of credit derivative." .

owl:AllDisjointClasses [ owl:members ( fis:InterestRateSwap fis:CurrencySwap fis:CreditDefaultSwap ) ] .

fis:OverTheCounterDerivative a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "Over-the-Counter Derivative" ;
    rdfs:comment "Derivative contract traded (and privately negotiated) directly between two parties, without going through an exchange or other intermediary." .

fis:ExchangeTradedDerivative a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "Exchange-Traded Derivative" ;
    rdfs:comment "Derivatives instruments traded via specialized derivatives exchanges or other exchanges." .

owl:AllDisjointClasses [ owl:members ( fis:OverTheCounterDerivative fis:ExchangeTradedDerivative ) ] .

#### Fund subtypes

fis:MutualFund a owl:Class ;
    rdfs:subClassOf fis:Fund ;
    rdfs:label "Mutual Fund" ;
    rdfs:comment "An investment fund that pools money from many investors to purchase securities; organized by a management company, technically owned by its members." .

fis:ExchangeTradedFund a owl:Class ;
    rdfs:subClassOf fis:Fund ;
    rdfs:label "Exchange-Traded Fund" ;
    rdfs:comment "An exchange-traded investment product registered as an open-end investment company or unit investment trust; shares trade on national securities exchanges at market prices that may differ from net asset value." .

owl:AllDisjointClasses [ owl:members ( fis:MutualFund fis:ExchangeTradedFund ) ] .

fis:MoneyMarketFund a owl:Class ;
    rdfs:subClassOf fis:MutualFund ;
    rdfs:label "Money Market Fund" ;
    rdfs:comment "A collective investment undertaking that primarily invests in money market instruments and/or other transferable debt instruments with residual maturity up to one year." .

fis:BondFund a owl:Class ;
    rdfs:subClassOf fis:MutualFund ;
    rdfs:label "Bond Fund" ;
    rdfs:comment "Also called income fund; a fund that invests primarily in bonds or other types of debt securities." .

fis:EquityFund a owl:Class ;
    rdfs:subClassOf fis:MutualFund ;
    rdfs:label "Equity Fund" ;
    rdfs:comment "Also called stock fund; a fund that invests primarily in stocks or equities." .

fis:HybridFund a owl:Class ;
    rdfs:subClassOf fis:MutualFund ;
    rdfs:label "Hybrid Fund" ;
    rdfs:comment "A fund that blends equity and fixed-income investments." .

fis:IndexFund a owl:Class ;
    rdfs:subClassOf fis:Fund ;
    rdfs:label "Index Fund" ;
    rdfs:comment "A passively managed fund that tracks the performance of an index such as a stock market index or bond market index." .

fis:ActivelyManagedFund a owl:Class ;
    rdfs:subClassOf fis:Fund ;
    rdfs:label "Actively Managed Fund" ;
    rdfs:comment "A fund that seeks to outperform stock market indices but generally charges higher fees, relying on active security selection by a manager." .

owl:AllDisjointClasses [ owl:members ( fis:IndexFund fis:ActivelyManagedFund ) ] .

fis:OpenEndFund a owl:Class ;
    rdfs:subClassOf fis:Fund ;
    rdfs:label "Open-End Fund" ;
    rdfs:comment "Fund purchased from or sold to the issuer at the net asset value of each share as of the close of the trading day." .

fis:ClosedEndFund a owl:Class ;
    rdfs:subClassOf fis:Fund ;
    rdfs:label "Closed-End Fund" ;
    rdfs:comment "A fund structure with a fixed number of shares not continuously issued or redeemed by the fund." .

fis:UnitInvestmentTrust a owl:Class ;
    rdfs:subClassOf fis:Fund ;
    rdfs:label "Unit Investment Trust" ;
    rdfs:comment "A primary structure of mutual fund pooling, alongside open-end and closed-end funds." .

owl:AllDisjointClasses [ owl:members ( fis:OpenEndFund fis:ClosedEndFund fis:UnitInvestmentTrust ) ] .

fis:HedgeFund a owl:Class ;
    rdfs:subClassOf fis:Fund ;
    rdfs:label "Hedge Fund" ;
    rdfs:comment "A fund that pools money from investors, like mutual funds, but with fewer regulations to protect investors and more risky and flexible strategies such as leverage and short-selling." .

#################################################################
# Issuer taxonomy
#################################################################

fis:Issuer a owl:Class ;
    rdfs:label "Issuer" ;
    rdfs:comment "The company or other entity issuing the security; the entity which is obligated on a security or other financial instrument." .

fis:SovereignGovernment a owl:Class ;
    rdfs:subClassOf fis:Issuer ;
    rdfs:label "Sovereign Government" ;
    rdfs:comment "A national government that issues government/treasury bonds." .

fis:LocalGovernment a owl:Class ;
    rdfs:subClassOf fis:Issuer ;
    rdfs:label "Local Government" ;
    rdfs:comment "A state, provincial, territorial, municipal or other governmental unit other than a sovereign government." .

fis:SupranationalOrganization a owl:Class ;
    rdfs:subClassOf fis:Issuer ;
    rdfs:label "Supranational Organization" ;
    rdfs:comment "An international organization such as the World Bank, IMF, or regional multilateral development banks." .

fis:Corporation a owl:Class ;
    rdfs:subClassOf fis:Issuer ;
    rdfs:label "Corporation" ;
    rdfs:comment "A commercial or industrial entity that may issue corporate bonds or stock." .

owl:AllDisjointClasses [ owl:members ( fis:SovereignGovernment fis:LocalGovernment fis:SupranationalOrganization fis:Corporation ) ] .

#################################################################
# Participant / holder related classes
#################################################################

fis:Shareholder a owl:Class ;
    rdfs:label "Shareholder" ;
    rdfs:comment "An individual or company that legally owns one or more shares of stock in a joint stock company; also called stockholder." .

fis:Bondholder a owl:Class ;
    rdfs:label "Bondholder" ;
    rdfs:comment "The holder of a bond, entitled to payment of principal and interest; a creditor of the issuer." .

fis:Investor a owl:Class ;
    rdfs:label "Investor" ;
    rdfs:comment "A person or institution investing in securities." .

fis:RetailInvestor a owl:Class ;
    rdfs:subClassOf fis:Investor ;
    rdfs:label "Retail Investor" ;
    rdfs:comment "A member of the public investing personally, other than by way of business." .

fis:InstitutionalInvestor a owl:Class ;
    rdfs:subClassOf fis:Investor ;
    rdfs:label "Institutional Investor" ;
    rdfs:comment "Financial institutions acting on their own account or on behalf of clients, including investment banks, insurance companies, pension funds and other managed funds." .

owl:AllDisjointClasses [ owl:members ( fis:RetailInvestor fis:InstitutionalInvestor ) ] .

#################################################################
# Other supporting classes
#################################################################

fis:CreditRating a owl:Class ;
    rdfs:label "Credit Rating" ;
    rdfs:comment "A rating assigned by a credit rating agency indicating credit quality of an issuer or security." .

fis:StockExchange a owl:Class ;
    rdfs:label "Stock Exchange" ;
    rdfs:comment "An organized and officially recognized market on which securities can be bought and sold." .

fis:DerivativesExchange a owl:Class ;
    rdfs:label "Derivatives Exchange" ;
    rdfs:comment "A market where individuals trade standardized derivative contracts defined by the exchange, acting as intermediary to all related transactions." .

fis:ClearingHouse a owl:Class ;
    rdfs:label "Clearing House" ;
    rdfs:comment "An entity that stands between buyer and seller in a futures contract, insuring the contract and mitigating risk of default." .

fis:Underlying a owl:Class ;
    rdfs:label "Underlying" ;
    rdfs:comment "The asset (commodity, financial instrument, price index, currency, interest rate, or event) upon which a derivative's value depends." .

#################################################################
# OBJECT PROPERTIES
#################################################################

fis:hasIssuer a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Security ;
    rdfs:range fis:Issuer ;
    rdfs:label "has issuer" ;
    rdfs:comment "Relates a security to the entity obligated on it; the company or other entity issuing the security. A security has exactly one issuer." .

fis:isIssuerOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasIssuer ;
    rdfs:domain fis:Issuer ;
    rdfs:range fis:Security ;
    rdfs:label "is issuer of" .

fis:hasHolder a owl:ObjectProperty ;
    rdfs:domain fis:Security ;
    rdfs:range fis:Investor ;
    rdfs:label "has holder" ;
    rdfs:comment "Relates a security to an investor holding it." .

fis:isHolderOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasHolder ;
    rdfs:domain fis:Investor ;
    rdfs:range fis:Security ;
    rdfs:label "is holder of" .

fis:hasUnderlying a owl:ObjectProperty ;
    rdfs:domain fis:Derivative ;
    rdfs:range fis:Underlying ;
    rdfs:label "has underlying" ;
    rdfs:comment "Relates a derivative to the underlying asset, rate, index, or event upon which its value depends." .

fis:isUnderlyingOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasUnderlying ;
    rdfs:domain fis:Underlying ;
    rdfs:range fis:Derivative ;
    rdfs:label "is underlying of" .

fis:hasCreditRating a owl:ObjectProperty ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range fis:CreditRating ;
    rdfs:label "has credit rating" ;
    rdfs:comment "Relates a debt security or issuer to its assigned credit rating." .

fis:isCreditRatingOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasCreditRating ;
    rdfs:domain fis:CreditRating ;
    rdfs:range fis:DebtSecurity ;
    rdfs:label "is credit rating of" .

fis:hasPortfolio a owl:ObjectProperty ;
    rdfs:domain fis:Fund ;
    rdfs:range fis:Security ;
    rdfs:label "has portfolio" ;
    rdfs:comment "Relates a fund to the securities it holds as part of its portfolio." .

fis:isPortfolioOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasPortfolio ;
    rdfs:domain fis:Security ;
    rdfs:range fis:Fund ;
    rdfs:label "is portfolio of" .

fis:isListedOn a owl:ObjectProperty ;
    rdfs:domain fis:Security ;
    rdfs:range fis:StockExchange ;
    rdfs:label "is listed on" ;
    rdfs:comment "Relates a security to the stock exchange on which it is listed." .

fis:hasListing a owl:ObjectProperty ;
    owl:inverseOf fis:isListedOn ;
    rdfs:domain fis:StockExchange ;
    rdfs:range fis:Security ;
    rdfs:label "has listing" .

fis:hasConversionTarget a owl:ObjectProperty ;
    rdfs:domain fis:ConvertibleBond ;
    rdfs:range fis:CommonStock ;
    rdfs:label "has conversion target" ;
    rdfs:comment "Relates a convertible bond to the common stock into which it may be converted." .

#################################################################
# DATATYPE PROPERTIES
#################################################################

fis:hasMaturityDate a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range xsd:date ;
    rdfs:label "has maturity date" ;
    rdfs:comment "The date on which the principal amount of a debt security is due to be repaid; a debt security has at most one maturity date (perpetual bonds have none)." .

fis:hasFaceValue a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range xsd:decimal ;
    rdfs:label "has face value" ;
    rdfs:comment "Also called par value, nominal, or principal amount; the amount on which the issuer pays interest and which must be repaid at maturity." .

fis:hasCouponRate a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:decimal ;
    rdfs:label "has coupon rate" ;
    rdfs:comment "The interest rate that the issuer pays to the holder, expressed in annual terms." .

fis:hasCouponPayment a owl:DatatypeProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:decimal ;
    rdfs:label "has coupon payment" ;
    rdfs:comment "The periodic dollar value of interest paid to a bondholder, determined by multiplying the face value by the coupon rate." .

fis:hasStrikePrice a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Option ;
    rdfs:range xsd:decimal ;
    rdfs:label "has strike price" ;
    rdfs:comment "Also known as exercise price; the price at which the underlying transaction will occur upon exercise of an option; fixed at issuance." .

fis:hasExpirationDate a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Option ;
    rdfs:range xsd:date ;
    rdfs:label "has expiration date" ;
    rdfs:comment "The last date on which an option can be exercised." .

fis:hasDeliveryDate a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Future ;
    rdfs:range xsd:date ;
    rdfs:label "has delivery date" ;
    rdfs:comment "The specified time in the future when delivery and payment occur under a futures contract." .

fis:hasNotionalAmount a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Swap ;
    rdfs:range xsd:decimal ;
    rdfs:label "has notional amount" ;
    rdfs:comment "The nominal amount used to calculate payments made on swaps; generally does not change hands between parties." .

fis:hasDividend a owl:DatatypeProperty ;
    rdfs:domain fis:Stock ;
    rdfs:range xsd:decimal ;
    rdfs:label "has dividend" ;
    rdfs:comment "A portion of a company's profit paid to shareholders; discretionary and not contractually guaranteed." .

fis:hasParValue a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:PreferredStock ;
    rdfs:range xsd:decimal ;
    rdfs:label "has par value" ;
    rdfs:comment "The fixed liquidation value associated with preferred stock, representing capital contributed when shares were first issued." .

fis:hasYieldToMaturity a owl:DatatypeProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:decimal ;
    rdfs:label "has yield to maturity" ;
    rdfs:comment "Also called redemption yield; the estimated total rate of return anticipated on a bond if held to maturity." .

fis:hasMarketPrice a owl:DatatypeProperty ;
    rdfs:domain fis:Security ;
    rdfs:range xsd:decimal ;
    rdfs:label "has market price" ;
    rdfs:comment "The price at which a security currently trades in the market." .

fis:hasTerm a owl:DatatypeProperty ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range xsd:string ;
    rdfs:label "has term" ;
    rdfs:comment "The length of time until the maturity date of a debt security, also referred to as tenor." .

#################################################################
# Additional axioms / comments on conflicting or notable statements
#################################################################

fis:PreferredStock rdfs:comment "Note: under IAS 32, a preference share that is mandatorily redeemable for cash is classified as a FinancialLiability rather than equity, diverging from the common market classification of preferred stock as equity/hybrid; this ontology follows the majority corpus view treating preferred stock as a hybrid equity-like security, noting the IAS 32 substance-over-form distinction as a conflicting perspective." .

fis:ConvertibleBond rdfs:comment "Note: under IAS 32, a convertible bond is treated as a compound instrument whose liability and equity components are presented separately, differing from the common market view of it as a single debt security with an embedded conversion feature; this ontology models ConvertibleBond as a single HybridSecurity/Bond per majority corpus usage." .

fis:Derivative rdfs:comment "Underlying can be an asset, index, interest rate, currency, or a factual/measurable event (e.g., credit default), per BIS and corpus definitions." .

```turtle
@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities> a owl:Ontology ;
  rdfs:comment "An OWL ontology modelling securities, financial instruments and derivatives, built from corpus passages describing their taxonomy and defining properties." .

#################################################################
#  TOP-LEVEL ASSET HIERARCHY
#################################################################

fis:Asset a owl:Class ;
  rdfs:label "asset" ;
  rdfs:comment "The underlying item a derivative or claim may reference: a commodity, a financial instrument, a price index, a currency, or an interest rate." .

fis:FinancialInstrument a owl:Class ;
  rdfs:subClassOf fis:Asset ;
  rdfs:label "financial instrument" ;
  rdfs:comment "A monetary contract between parties that can be created, traded, modified and settled (cash, debt, equity or derivative)." .

fis:Commodity a owl:Class ; rdfs:subClassOf fis:Asset .
fis:Currency a owl:Class ; rdfs:subClassOf fis:Asset .
fis:InterestRate a owl:Class ; rdfs:subClassOf fis:Asset .
fis:MarketIndex a owl:Class ; rdfs:subClassOf fis:Asset ; rdfs:label "price index" .

fis:CashInstrument a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:comment "An instrument whose value is determined directly by the markets: securities, or instruments such as loans and deposits where borrower and lender must agree on a transfer." .

fis:DerivativeInstrument a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:comment "An instrument which derives its value from the value and characteristics of one or more underlying entities. NOTE: one passage treats cash instruments and derivative instruments as a strict dichotomy of financial instruments, while another passage treats derivatives as one of three categories of securities (US law). Both views are modelled: fis:Derivative is a subclass of both fis:Security and fis:DerivativeInstrument." .

fis:Debt a owl:Class ;
  rdfs:subClassOf fis:Asset ;
  rdfs:comment "Debt-based financial instruments, reflecting a loan the investor has made to the issuing entity; comprises debt securities and loans." .

fis:Equity a owl:Class ;
  rdfs:subClassOf fis:Asset ;
  rdfs:comment "All instruments and records acknowledging claims on the residual value of a corporation or quasi-corporation after the claims of all creditors have been met; comprises equity securities and other financial instruments not classified as securities." .

#################################################################
#  SECURITY
#################################################################

fis:Security a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument, fis:CashInstrument ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:FinancialInstrument
      [ a owl:Restriction ; owl:onProperty fis:isTradable ; owl:hasValue true ]
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Issuer ]
    )
  ] ;
  rdfs:label "security" ;
  rdfs:comment "A tradable financial asset which entitles the holder to investment returns and represents a claim on the issuer that can be traded in financial markets." .

fis:Loan a owl:Class ; rdfs:subClassOf fis:Debt, fis:CashInstrument .
fis:Mortgage a owl:Class ; rdfs:subClassOf fis:Loan .
fis:ResidentialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage .
fis:CommercialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage .
fis:Deposit a owl:Class ; rdfs:subClassOf fis:CashInstrument .

fis:DividedSecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:comment "Each divided security constitutes a separate asset, legally distinct from every other security in the same issue." .

fis:UndividedSecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:comment "The entire issue makes up one single asset, with each security a fractional part of the undivided whole." .

#################################################################
#  EQUITY SECURITY FAMILY
#################################################################

fis:EquitySecurity a owl:Class ;
  rdfs:subClassOf fis:Equity, fis:Security ;
  rdfs:label "equity security" ;
  rdfs:comment "A share of equity interest in an entity such as the capital stock of a company, trust or partnership." .

fis:Stock a owl:Class ;
  rdfs:subClassOf fis:EquitySecurity ;
  rdfs:label "stock" , "share" ;
  rdfs:comment "Consists of all the shares by which ownership of a corporation or company is divided." .

fis:CommonStock a owl:Class ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Stock
      [ a owl:Restriction ; owl:onProperty fis:hasVotingRight ; owl:hasValue true ]
    )
  ] ;
  rdfs:label "common stock" , "ordinary share" .

fis:PreferredStock a owl:Class ;
  rdfs:subClassOf fis:HybridSecurity ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Stock
      [ a owl:Restriction ; owl:onProperty fis:hasVotingRight ; owl:hasValue false ]
    )
  ] ;
  rdfs:label "preferred stock" , "preference share" ;
  rdfs:comment "Senior to common stock and subordinate to bonds; typically does not carry voting rights but has priority in dividends and liquidation." .

fis:DepositaryReceipt a owl:Class ;
  rdfs:subClassOf fis:Security ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Security
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ]
    )
  ] ;
  rdfs:comment "A negotiable financial instrument issued by a bank to represent a foreign company's publicly traded securities." .

fis:AmericanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt .
fis:EuropeanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt .
fis:GlobalDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt .

#################################################################
#  HYBRID SECURITY FAMILY
#################################################################

fis:HybridSecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:comment "Combines some of the characteristics of both debt and equity securities." .

fis:EquityWarrant a owl:Class ;
  rdfs:subClassOf fis:Warrant, fis:HybridSecurity ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Warrant
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ]
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ]
    )
  ] ;
  rdfs:comment "Options issued by a company that allow the holder to purchase a specific number of shares at a specified price within a specified time." .

#################################################################
#  DEBT SECURITY FAMILY
#################################################################

fis:DebtSecurity a owl:Class ;
  rdfs:subClassOf fis:Debt, fis:Security ;
  rdfs:comment "Entitles the holder to payment of principal and interest; may be called debentures, bonds, deposits, notes or commercial paper." .

fis:Bond a owl:Class ;
  rdfs:subClassOf fis:DebtSecurity ;
  rdfs:comment "A bond is a type of security under which the issuer owes the holder a debt and is obliged to repay the principal and usually interest (the coupon)." .

fis:Debenture a owl:Class ;
  rdfs:subClassOf fis:Bond ;
  rdfs:comment "Unsecured bond having only a general claim on the issuer's assets and cash flows." .

fis:MoneyMarketInstrument a owl:Class ;
  rdfs:subClassOf fis:DebtSecurity ;
  rdfs:comment "Short-term debt instruments with original maturities of one year or less, highly liquid and sometimes called 'near cash'." .

fis:CommercialPaper a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "An unsecured promissory note with a fixed maturity of usually less than 270 days." .
fis:CertificateOfDeposit a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument .
fis:TreasuryBill a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument .
fis:RepurchaseAgreement a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument .
fis:BankersAcceptance a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument .

#### Bond classified by issuer

fis:GovernmentBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] ;
  rdfs:label "government bond" , "sovereign bond" , "treasury bond" ;
  rdfs:comment "Medium or long term debt securities issued by sovereign governments or their agencies." .

fis:MunicipalBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:MunicipalAuthority ] ) ] ;
  rdfs:label "municipal bond" , "muni" ;
  rdfs:comment "A bond issued by state or local governments, or entities they create such as authorities and special districts." .

fis:CorporateBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] ;
  rdfs:comment "A bond issued by a corporation in order to raise financing." .

fis:SupranationalBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ] ) ] ;
  rdfs:label "supra" .

fis:WarBond a owl:Class ; rdfs:subClassOf fis:GovernmentBond .
fis:ClimateBond a owl:Class ; rdfs:subClassOf fis:Bond .

fis:GeneralObligationBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond .
fis:AssessmentBond a owl:Class ; rdfs:subClassOf fis:GeneralObligationBond .
fis:RevenueBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond .

#### Bond classified by maturity / coupon behaviour

fis:ZeroCouponBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasCouponRate ; owl:hasValue "0.0"^^xsd:decimal ] ) ] ;
  rdfs:comment "Pays no regular interest; sold at a substantial discount to par value." .

fis:FixedRateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Coupon remains constant throughout the life of the bond." .
fis:FloatingRateNote a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Coupon varies, linked to a reference rate of interest." .
fis:InflationIndexedBond a owl:Class ; rdfs:subClassOf fis:Bond .
fis:PerpetualBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "A bond with no maturity date (irredeemable), also called a perpetuity." .
fis:SerialBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Matures in instalments over a period of time." .

#### Bond classified by optionality

fis:CallableBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasCallPrice ; owl:someValuesFrom xsd:decimal ] ) ] ;
  rdfs:comment "Gives the issuer the right to repay the bond before the maturity date." .

fis:PutableBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasPutPrice ; owl:someValuesFrom xsd:decimal ] ) ] ;
  rdfs:label "retractable bond" ;
  rdfs:comment "Gives the holder the right to force the issuer to repay the bond before maturity." .

fis:ConvertibleBond a owl:Class ;
  rdfs:subClassOf fis:HybridSecurity ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasConversionRatio ; owl:someValuesFrom xsd:decimal ] ) ] ;
  rdfs:comment "A bond the holder can convert into a specified number of shares of the issuer's common stock." .

fis:ExchangeableBond a owl:Class ;
  rdfs:subClassOf fis:Bond ;
  rdfs:comment "Allows exchange into shares of a corporation other than the issuer." .

#### Bond classified by seniority

fis:SeniorBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasSeniority ; owl:hasValue "senior" ] ) ] .
fis:SubordinatedBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasSeniority ; owl:hasValue "subordinated" ] ) ] .

#### Bond classified by credit rating

fis:InvestmentGradeBond a owl:Class ; rdfs:subClassOf fis:Bond ; rdfs:label "high grade bond" .
fis:HighYieldBond a owl:Class ; rdfs:subClassOf fis:Bond ; rdfs:label "junk bond" .

#### Bond classified by registration form (applies to securities generally)

fis:BearerBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasRegistrationForm ; owl:hasValue "bearer" ] ) ] .
fis:RegisteredBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasRegistrationForm ; owl:hasValue "registered" ] ) ] .
fis:BookEntryBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasRegistrationForm ; owl:hasValue "book-entry" ] ) ] .

#### Asset-backed family

fis:AssetBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Asset ] ) ] ;
  rdfs:label "ABS" ;
  rdfs:comment "Bonds whose interest and principal payments are backed by underlying cash flows from other assets." .

fis:CoveredBond a owl:Class ;
  rdfs:subClassOf fis:Bond ;
  owl:disjointWith fis:AssetBackedSecurity ;
  rdfs:comment "Backed by cash flows from mortgages or public-sector assets; unlike asset-backed securities, these assets remain on the issuer's balance sheet." .

fis:MortgageBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Mortgage ] ) ] ;
  rdfs:label "MBS" .

fis:ResidentialMortgageBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MortgageBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:ResidentialMortgage ] ) ] ;
  rdfs:label "RMBS" .

fis:CommercialMortgageBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MortgageBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:CommercialMortgage ] ) ] ;
  rdfs:label "CMBS" .

fis:CollateralizedMortgageObligation a owl:Class ;
  rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:label "CMO" , "pay-through bond" .

fis:CollateralizedDebtObligation a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:DebtSecurity ] ) ] ;
  rdfs:label "CDO" ;
  rdfs:comment "A type of structured asset-backed security sliced into tranches catching cash flow in sequence based on seniority." .

#################################################################
#  DERIVATIVE FAMILY
#################################################################

fis:Derivative a owl:Class ;
  rdfs:subClassOf fis:Security, fis:DerivativeInstrument ;
  rdfs:comment "A contract whose value depends on the performance of an underlier such as a commodity, financial instrument, price index, currency, or interest rate." .

fis:Forward a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
      [ a owl:Restriction ; owl:onProperty fis:hasObligatoryPerformance ; owl:hasValue true ]
      [ a owl:Restriction ; owl:onProperty fis:isExchangeTraded ; owl:hasValue false ]
      [ a owl:Restriction ; owl:onProperty fis:hasDeliveryDate ; owl:someValuesFrom xsd:date ]
  ) ] ;
  rdfs:comment "A non-standardized contract between two parties to buy or sell an asset at a specified future time at a price agreed today." .

fis:Future a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
      [ a owl:Restriction ; owl:onProperty fis:hasObligatoryPerformance ; owl:hasValue true ]
      [ a owl:Restriction ; owl:onProperty fis:isExchangeTraded ; owl:hasValue true ]
      [ a owl:Restriction ; owl:onProperty fis:hasDeliveryDate ; owl:someValuesFrom xsd:date ]
  ) ] ;
  rdfs:comment "A standardized legal contract to buy or sell something at a predetermined price for delivery at a specified future time." .

fis:StockFuture a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Future
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ] ) ] .

fis:Option a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
      [ a owl:Restriction ; owl:onProperty fis:hasObligatoryPerformance ; owl:hasValue false ]
      [ a owl:Restriction ; owl:onProperty fis:hasStrikePrice ; owl:someValuesFrom xsd:decimal ]
      [ a owl:Restriction ; owl:onProperty fis:hasExpirationDate ; owl:someValuesFrom xsd:date ]
  ) ] ;
  rdfs:comment "Gives the buyer the right, but not the obligation, to buy or sell an underlying asset at a specified strike price on or before a specified date." .

fis:CallOption a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasOptionType ; owl:hasValue "call" ] ) ] .
fis:PutOption a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasOptionType ; owl:hasValue "put" ] ) ] .

fis:AmericanOption a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "American" ] ) ] ;
  rdfs:comment "May be exercised on any trading day on or before expiration." .
fis:EuropeanOption a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "European" ] ) ] ;
  rdfs:comment "May only be exercised on expiry." .
fis:BermudanOption a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "Bermudan" ] ) ] ;
  rdfs:comment "May be exercised only on specified dates on or before expiration." .

fis:AsianOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "Payoff determined by the average underlying price over a preset period." .
fis:BarrierOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "The underlying price must pass a certain barrier before the option can be exercised." .
fis:BinaryOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "An all-or-nothing option that pays the full amount if a defined condition is met at expiration." .
fis:ExoticOption a owl:Class ; rdfs:subClassOf fis:Option .

fis:StockOption a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ] ) ] .

fis:Warrant a owl:Class ;
  rdfs:subClassOf fis:Option ;
  rdfs:comment "A long-dated option, generally traded over the counter." .

fis:Swap a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
      [ a owl:Restriction ; owl:onProperty fis:hasObligatoryPerformance ; owl:hasValue true ]
      [ a owl:Restriction ; owl:onProperty fis:hasNotionalAmount ; owl:someValuesFrom xsd:decimal ]
  ) ] ;
  rdfs:comment "Two counterparties exchange cash flows of one financial instrument for those of another." .

fis:InterestRateSwap a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Swap
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:InterestRate ] ) ] .
fis:CurrencySwap a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Swap
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Currency ] ) ] .
fis:EquitySwap a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Swap
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ] ) ] .
fis:CreditDefaultSwap a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Swap
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:DebtSecurity ] ) ] ;
  rdfs:label "CDS" ;
  rdfs:comment "The seller compensates the buyer in the event of a loan default or other credit event on a reference entity." .

#### Derivative classified by underlying type

fis:EquityDerivative a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ] ) ] ;
  rdfs:comment "A stock derivative: any financial instrument for which the underlying asset is the price of an equity." .
fis:InterestRateDerivative a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:InterestRate ] ) ] .
fis:CurrencyDerivative a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Currency ] ) ] .
fis:CommodityDerivative a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Commodity ] ) ] .
fis:CreditDerivative a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:DebtSecurity ] ) ] .

#################################################################
#  FUND FAMILY
#################################################################

fis:Fund a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:comment "An investment fund that pools money from many investors to purchase securities." .

fis:MutualFund a owl:Class ; rdfs:subClassOf fis:Fund .
fis:OpenEndFund a owl:Class ; rdfs:subClassOf fis:MutualFund .
fis:ClosedEndFund a owl:Class ; rdfs:subClassOf fis:MutualFund .
fis:UnitInvestmentTrust a owl:Class ; rdfs:subClassOf fis:MutualFund .

fis:MoneyMarketFund a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Fund
      [ a owl:Restriction ; owl:onProperty fis:hasPortfolio ; owl:someValuesFrom fis:MoneyMarketInstrument ] ) ] .
fis:BondFund a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Fund
      [ a owl:Restriction ; owl:onProperty fis:hasPortfolio ; owl:someValuesFrom fis:Bond ] ) ] .
fis:EquityFund a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Fund
      [ a owl:Restriction ; owl:onProperty fis:hasPortfolio ; owl:someValuesFrom fis:EquitySecurity ] ) ] .
fis:IndexFund a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Fund
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:MarketIndex ] ) ] ;
  rdfs:comment "Passively managed fund that tracks the performance of a market index." .
fis:ActivelyManagedFund a owl:Class ; rdfs:subClassOf fis:Fund .

fis:ExchangeTradedFund a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Fund
      [ a owl:Restriction ; owl:onProperty fis:isExchangeTraded ; owl:hasValue true ] ) ] ;
  rdfs:label "ETF" .

fis:HedgeFund a owl:Class ;
  rdfs:subClassOf fis:Fund ;
  rdfs:comment "Pools money from investors like a mutual fund, but with fewer regulations protecting investors and more flexible, riskier strategies." .

#################################################################
#  DIVIDEND
#################################################################

fis:Dividend a owl:Class ;
  rdfs:label "dividend" ;
  rdfs:comment "A discretionary portion of a company's profit paid to shareholders; unlike a bond coupon, there is no contractual obligation to pay it." .

#################################################################
#  ISSUER / INVESTOR / MARKET
#################################################################

fis:Issuer a owl:Class ;
  rdfs:comment "The entity which is obligated on a security or other financial instrument; the company or other entity issuing the security." .

fis:SovereignGovernment a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:MunicipalAuthority a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:Corporation a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:SupranationalOrganization a owl:Class ; rdfs:subClassOf fis:Issuer .

fis:Investor a owl:Class ;
  rdfs:comment "A person or institution that invests in securities." .
fis:RetailInvestor a owl:Class ; rdfs:subClassOf fis:Investor ;
  rdfs:comment "Members of the public investing personally, other than by way of business." .
fis:WholesaleInvestor a owl:Class ; rdfs:subClassOf fis:Investor ;
  rdfs:label "institutional investor" ;
  rdfs:comment "Financial institutions acting on their own account, or on behalf of clients." .

fis:Market a owl:Class .
fis:StockExchange a owl:Class ; rdfs:subClassOf fis:Market ;
  rdfs:comment "An organized and officially recognized market on which securities can be bought and sold." .
fis:OverTheCounterMarket a owl:Class ; rdfs:subClassOf fis:Market ; rdfs:label "OTC market" .
fis:PrimaryMarket a owl:Class ; rdfs:subClassOf fis:Market ;
  rdfs:comment "The market for new securities, in which the issuer receives the sale proceeds." .
fis:SecondaryMarket a owl:Class ; rdfs:subClassOf fis:Market ;
  rdfs:comment "The market for already-issued securities, where proceeds do not go to the original issuer." .
fis:BondMarket a owl:Class ; rdfs:subClassOf fis:Market .
fis:MoneyMarket a owl:Class ; rdfs:subClassOf fis:Market .
fis:EquityMarket a owl:Class ; rdfs:subClassOf fis:Market ; rdfs:label "stock market" .

fis:SecurityOffering a owl:Class ;
  rdfs:comment "The manner in which securities are offered to investors in the primary market." .
fis:PublicOffering a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:SecurityOffering
      [ a owl:Restriction ; owl:onProperty fis:isPrivate ; owl:hasValue false ] ) ] .
fis:PrivatePlacement a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:SecurityOffering
      [ a owl:Restriction ; owl:onProperty fis:isPrivate ; owl:hasValue true ] ) ] ;
  rdfs:comment "Offered privately to a limited number of qualified persons; not publicly tradable." .

#################################################################
#  MEASUREMENT CATEGORY (IFRS 9)
#################################################################

fis:MeasurementCategory a owl:Class ;
  rdfs:comment "IFRS 9 subsequent-measurement classification of a financial asset." .
fis:AmortizedCostMeasurement a owl:Class ; rdfs:subClassOf fis:MeasurementCategory .
fis:FairValueThroughProfitOrLossMeasurement a owl:Class ; rdfs:subClassOf fis:MeasurementCategory ; rdfs:label "FVTPL" .
fis:FairValueThroughOtherComprehensiveIncomeMeasurement a owl:Class ; rdfs:subClassOf fis:MeasurementCategory ; rdfs:label "FVOCI" .

fis:Derivative rdfs:subClassOf [
  a owl:Restriction ;
  owl:onProperty fis:hasMeasurementCategory ;
  owl:hasValue fis:FairValueThroughProfitOrLossMeasurement
] .

#################################################################
#  OBJECT PROPERTIES
#################################################################

fis:hasIssuer a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ;
  rdfs:range fis:Issuer ;
  rdfs:comment "The company or other entity issuing the security is called the issuer." .

fis:isIssuerOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasIssuer ;
  rdfs:domain fis:Issuer ;
  rdfs:range fis:Security .

fis:hasUnderlying a owl:ObjectProperty ;
  rdfs:domain fis:FinancialInstrument ;
  rdfs:range fis:Asset ;
  rdfs:comment "The asset upon which a derivative or depositary receipt is based." .

fis:isUnderlyingOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasUnderlying ;
  rdfs:domain fis:Asset ;
  rdfs:range fis:FinancialInstrument .

fis:hasCollateral a owl:ObjectProperty ;
  rdfs:domain fis:Bond ;
  rdfs:range fis:Asset ;
  rdfs:comment "The pool of assets backing an asset-backed or covered bond." .

fis:isCollateralOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasCollateral ;
  rdfs:domain fis:Asset ;
  rdfs:range fis:Bond .

fis:hasDividend a owl:ObjectProperty ;
  rdfs:domain fis:Stock ;
  rdfs:range fis:Dividend .

fis:hasPortfolio a owl:ObjectProperty ;
  rdfs:domain fis:Fund ;
  rdfs:range fis:FinancialInstrument ;
  rdfs:comment "The combined holdings a fund owns." .

fis:isListedOn a owl:ObjectProperty ;
  rdfs:domain fis:Security ;
  rdfs:range fis:StockExchange .

fis:hasHolder a owl:ObjectProperty ;
  rdfs:domain fis:Security ;
  rdfs:range fis:Investor .

fis:hasOffering a owl:ObjectProperty ;
  rdfs:domain fis:Security ;
  rdfs:range fis:SecurityOffering .

fis:hasMeasurementCategory a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:FinancialInstrument ;
  rdfs:range fis:MeasurementCategory .

#################################################################
#  DATATYPE PROPERTIES
#################################################################

fis:isTradable a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:FinancialInstrument ;
  rdfs:range xsd:boolean .

fis:isExchangeTraded a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ;
  rdfs:range xsd:boolean .

fis:hasObligatoryPerformance a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Derivative ;
  rdfs:range xsd:boolean ;
  rdfs:comment "True for 'lock' products (forwards, futures, swaps) which obligate both parties; false for 'option' products." .

fis:hasFaceValue a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Bond ;
  rdfs:range xsd:decimal ;
  rdfs:label "par value" , "face amount" .

fis:hasMaturityDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Bond ;
  rdfs:range xsd:date .

fis:hasCouponRate a owl:DatatypeProperty ;
  rdfs:domain fis:Bond ;
  rdfs:range xsd:decimal .

fis:hasYield a owl:DatatypeProperty ;
  rdfs:domain fis:Bond ;
  rdfs:range xsd:decimal .

fis:hasCreditRating a owl:DatatypeProperty ;
  rdfs:domain fis:Bond ;
  rdfs:range xsd:string .

fis:hasCallPrice a owl:DatatypeProperty ;
  rdfs:domain fis:Bond ;
  rdfs:range xsd:decimal .

fis:hasPutPrice a owl:DatatypeProperty ;
  rdfs:domain fis:Bond ;
  rdfs:range xsd:decimal .

fis:hasConversionRatio a owl:DatatypeProperty ;
  rdfs:domain fis:Bond ;
  rdfs:range xsd:decimal .

fis:hasConversionPrice a owl:DatatypeProperty ;
  rdfs:domain fis:Bond ;
  rdfs:range xsd:decimal .

fis:hasSeniority a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Bond ;
  rdfs:range xsd:string .

fis:hasRegistrationForm a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ;
  rdfs:range xsd:string ;
  rdfs:comment "Whether a certificate is 'bearer', 'registered' or 'book-entry'." .

fis:hasStrikePrice a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ;
  rdfs:range xsd:decimal .

fis:hasExpirationDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ;
  rdfs:range xsd:date .

fis:hasPremium a owl:DatatypeProperty ;
  rdfs:domain fis:Option ;
  rdfs:range xsd:decimal .

fis:hasOptionType a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ;
  rdfs:range xsd:string ;
  rdfs:comment "'call' or 'put'." .

fis:hasExerciseStyle a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ;
  rdfs:range xsd:string ;
  rdfs:comment "'American', 'European' or 'Bermudan'." .

fis:hasDeliveryDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Derivative ;
  rdfs:range xsd:date .

fis:hasDeliveryPrice a owl:DatatypeProperty ;
  rdfs:domain fis:Derivative ;
  rdfs:range xsd:decimal .

fis:hasNotionalAmount a owl:DatatypeProperty ;
  rdfs:domain fis:Swap ;
  rdfs:range xsd:decimal .

fis:hasVotingRight a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:EquitySecurity ;
  rdfs:range xsd:boolean .

fis:hasDividendAmount a owl:DatatypeProperty ;
  rdfs:domain fis:Dividend ;
  rdfs:range xsd:decimal .

fis:isOpenEnded a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Fund ;
  rdfs:range xsd:boolean .

fis:isPrivate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:SecurityOffering ;
  rdfs:range xsd:boolean .

#################################################################
#  DISJOINTNESS
#################################################################

[] a owl:AllDisjointClasses ;
  owl:members ( fis:Security fis:Loan fis:Deposit ) .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:DebtSecurity fis:EquitySecurity fis:Derivative ) .
# NOTE: fis:HybridSecurity deliberately overlaps both DebtSecurity and EquitySecurity
# (e.g. PreferredStock, ConvertibleBond) and is therefore not included in this disjoint set,
# reflecting the corpus statement that hybrid securities combine debt and equity features.

[] a owl:AllDisjointClasses ;
  owl:members ( fis:Bond fis:MoneyMarketInstrument ) .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:CommonStock fis:PreferredStock ) .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:CallOption fis:PutOption ) .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:AmericanOption fis:EuropeanOption fis:BermudanOption ) .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:Future fis:Forward ) .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:BearerBond fis:RegisteredBond fis:BookEntryBond ) .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:SeniorBond fis:SubordinatedBond ) .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:HighYieldBond fis:InvestmentGradeBond ) .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:GovernmentBond fis:MunicipalBond fis:CorporateBond fis:SupranationalBond ) .

